// THE USER-FACING NATIVE LSDj STRUCTURE EDITOR.
//
// Reached from Create's "Open LSDj" control. It opens a local .lsdsng or .sav,
// makes a NativeDocument (src/lsdj-native-document.js) the SOLE authority for
// the native edit, and lets a person edit the actual native slots/rows -- the
// sequence, chains, phrases, instrument params, all five table columns, the
// grooves and the wave frames -- as raw hex bytes. Untouched bytes are
// preserved by the document; unrelated Create flattened scores are never
// touched or re-exported through this path.
//
// WHAT THIS IS NOT: a player. Entering it STOPS whatever Create was playing and
// states plainly that native playback is not implemented. Nothing here sounds,
// and no approximation is presented as parity -- this is byte-level structural
// editing, not semantic support.
//
// Export goes straight from document.toSong() through the real LSDj compressor
// and header (never fromDocument). A .sav is only written when a .sav was
// opened, updating its first 32768 working-memory bytes and keeping the rest.
// The uploaded file is never overwritten; downloads are new files. Native
// sharing is a standalone serializeFull() JSON file -- a document to reopen
// here, clearly not a playable link.
(function (G) {
  'use strict';

  var panel = null, fileInput = null, jsonInput = null;
  var state = null;                 // { doc, savBytes, title, dirty }
  var curCat = 0, curSlot = 0;

  function LS() { return G.CT_LSDJ; }
  function DOC() { return G.CT_LSDJ_DOC; }

  function hex2(v) { return ('0' + (v & 0xFF).toString(16).toUpperCase()).slice(-2); }
  function parseHexByte(s) {
    if (!/^[0-9a-fA-F]{1,2}$/.test(s)) return null;
    var v = parseInt(s, 16);
    return (v >= 0 && v <= 255) ? v : null;
  }
  function safeName(t) {
    return (String(t || 'lsdj').replace(/[^A-Za-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'lsdj').slice(0, 24);
  }
  // LSDj's eight-character project name alphabet.
  function projName(t) {
    var s = String(t || 'CHIPTUNE').toUpperCase().replace(/[^A-Z0-9 -]/g, '').trim();
    if (!s) s = 'CHIPTUNE';
    var out = new Uint8Array(8);
    for (var i = 0; i < 8; i++) out[i] = i < s.length ? s.charCodeAt(i) : 0;
    return out;
  }

  // Generic, structural (not semantic) byte categories. Each column addresses a
  // single native field byte; labels for unproven columns stay neutral (the raw
  // field name) rather than claiming a meaning.
  function at(key) { return function (s, r) { return { key: key, i: s, j: r }; }; }
  var CATS = [
    { id: 'sequence', label: 'Sequence', unit: 'row', slots: 256, rows: 1, rowLabel: '',
      cols: [
        { l: 'PU1', at: function (s) { return { key: 'sequence', i: s, j: 0 }; } },
        { l: 'PU2', at: function (s) { return { key: 'sequence', i: s, j: 1 }; } },
        { l: 'WAV', at: function (s) { return { key: 'sequence', i: s, j: 2 }; } },
        { l: 'NOI', at: function (s) { return { key: 'sequence', i: s, j: 3 }; } }
      ] },
    { id: 'chains', label: 'Chains', unit: 'chain', slots: 128, rows: 16, rowLabel: 'Row',
      cols: [ { l: 'Phrase', at: at('chainPhrases') }, { l: 'Transpose', at: at('chainTranspose') } ] },
    { id: 'phrases', label: 'Phrases', unit: 'phrase', slots: 255, rows: 16, rowLabel: 'Step',
      cols: [ { l: 'Note', at: at('phraseNotes') }, { l: 'Inst', at: at('phraseInstruments') },
              { l: 'Cmd', at: at('phraseCommands') }, { l: 'Val', at: at('phraseCommandVals') } ] },
    { id: 'instruments', label: 'Instruments', unit: 'instrument', slots: 64, rows: 16, rowLabel: 'Byte',
      cols: [ { l: 'Param', at: at('instrumentParams') } ] },
    { id: 'tables', label: 'Tables', unit: 'table', slots: 32, rows: 16, rowLabel: 'Row',
      cols: [ { l: 'tables0', at: at('tables0') }, { l: 'tables1', at: at('tables1') },
              { l: 'tables2', at: at('tables2') }, { l: 'cmd', at: at('tableCommands') },
              { l: 'val', at: at('tableValues') } ] },
    { id: 'groove', label: 'Groove', unit: 'groove', slots: 32, rows: 16, rowLabel: 'Step',
      cols: [ { l: 'Ticks', at: at('grooves') } ] },
    { id: 'waves', label: 'Waves', unit: 'wave', slots: 256, rows: 16, rowLabel: 'Byte',
      cols: [ { l: 'Sample', at: at('waves') } ] }
  ];

  function getByte(cat, slot, row, ci) {
    var a = cat.cols[ci].at(slot, row);
    return state.doc.fieldRow(a.key, a.i)[a.j];
  }
  function status(m) { var s = panel && panel.querySelector('.ne-status'); if (s) s.textContent = m; }
  function toast(m) { if (G._toast) G._toast(m); status(m); }
  function saveBytes(bytes, name, type) {
    try {
      var blob = new Blob([bytes], { type: type || 'application/octet-stream' });
      if (G._saveBlob) { G._saveBlob(blob, name); return true; }
      var url = URL.createObjectURL(blob), a = document.createElement('a');
      a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
      return true;
    } catch (e) { return false; }
  }

  // ---- inputs (created once, hidden) -------------------------------------
  function ensureInputs() {
    if (!fileInput) {
      fileInput = document.createElement('input');
      fileInput.type = 'file'; fileInput.accept = '.lsdsng,.sav';
      fileInput.style.display = 'none'; fileInput.setAttribute('aria-hidden', 'true');
      fileInput.addEventListener('change', function () {
        var f = fileInput.files && fileInput.files[0]; fileInput.value = '';
        if (f) openFromFile(f);
      });
      document.body.appendChild(fileInput);
    }
    if (!jsonInput) {
      jsonInput = document.createElement('input');
      jsonInput.type = 'file'; jsonInput.accept = '.json,application/json';
      jsonInput.style.display = 'none'; jsonInput.setAttribute('aria-hidden', 'true');
      jsonInput.addEventListener('change', function () {
        var f = jsonInput.files && jsonInput.files[0]; jsonInput.value = '';
        if (f) importJsonFile(f);
      });
      document.body.appendChild(jsonInput);
    }
  }
  function pick() { ensureInputs(); fileInput.click(); }

  // ---- open a local .lsdsng / .sav ---------------------------------------
  // Reject invalid/oversized uploads by their metadata BEFORE reading them, and
  // never disturb the current document until a valid song has been parsed.
  function openFromFile(f) {
    var lower = String(f.name || '').toLowerCase();
    var isSav = /\.sav$/.test(lower), isSng = /\.lsdsng$/.test(lower);
    if (!isSav && !isSng) { toast('Choose a .lsdsng or .sav file'); return; }
    if (isSav && f.size !== 0x20000) { toast('A .sav must be exactly 128 KB'); return; }
    if (isSng && (f.size < 10 || f.size > 200000)) { toast('That .lsdsng is not a valid size'); return; }
    if (!LS() || !DOC()) { toast('LSDj support is unavailable in this build'); return; }
    var rd = new FileReader();
    rd.onerror = function () { toast('Could not read that file'); };
    rd.onload = function () {
      try {
        var bytes = new Uint8Array(rd.result), song, sav = null, name = 'CHIPTUNE';
        if (isSav) { var p = LS().parseSav(bytes); song = p.song; sav = Uint8Array.from(bytes); name = 'WORKMEM'; }
        else { var q = LS().parseLsdsng(bytes); song = q.song; name = q.name || 'CHIPTUNE'; }
        var d = DOC().NativeDocument.fromSong(song, { title: name });
        open({ doc: d, savBytes: sav, name: name });          // only now do we enter
      } catch (e) { toast('That file is not a valid LSDj song'); }   // current document untouched
    };
    rd.readAsArrayBuffer(f);
  }
  function importJsonFile(f) {
    if (!f) return;
    if (f.size > 400000) { toast('That native JSON is too large'); return; }
    if (!DOC()) { toast('LSDj support is unavailable in this build'); return; }
    var rd = new FileReader();
    rd.onerror = function () { toast('Could not read that file'); };
    rd.onload = function () {
      try {
        var d = DOC().NativeDocument.deserialize(String(rd.result));
        open({ doc: d, savBytes: null, name: d.title() || 'CHIPTUNE' });
        status('Opened native structure from JSON (structure only, no playback)');
      } catch (e) { toast('That native JSON is not valid'); }        // current document untouched
    };
    rd.readAsText(f);
  }

  // ---- panel --------------------------------------------------------------
  function buildPanel() {
    if (panel) return;
    panel = document.createElement('div');
    panel.id = 'nativeeditor';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-modal', 'false');
    panel.setAttribute('aria-label', 'LSDj native structure editor');
    panel.innerHTML =
      '<div class="ne-top">' +
        '<div class="ne-title"><b>LSDj</b> <span class="ne-name"></span></div>' +
        '<button type="button" class="ne-close" aria-label="Close native editor" title="Close">\u2715</button>' +
      '</div>' +
      '<p class="ne-banner" role="note">Structural editor \u2014 native playback is <b>not implemented</b>. ' +
        'Edits change raw bytes only; nothing here plays, and no sound approximation is claimed.</p>' +
      '<div class="ne-cats" role="tablist" aria-label="Native field category"></div>' +
      '<div class="ne-bar">' +
        '<label class="ne-slotlab">Slot <input class="ne-slot" type="number" min="0" step="1" value="0" ' +
          'inputmode="numeric" aria-label="Slot index"></label>' +
        '<span class="ne-slothex"></span>' +
        '<span class="ne-sp"></span>' +
        '<button type="button" class="ne-btn ne-undo">\u21A9 Undo</button>' +
        '<button type="button" class="ne-btn ne-redo">\u21AA Redo</button>' +
        '<span class="ne-sp"></span>' +
        '<button type="button" class="ne-btn ne-exp-sng">Save .lsdsng</button>' +
        '<button type="button" class="ne-btn ne-exp-sav">Save .sav</button>' +
        '<button type="button" class="ne-btn ne-exp-json" title="Structure only \u2014 a file to reopen here, not a playable link">Save native JSON</button>' +
        '<button type="button" class="ne-btn ne-imp-json">Open native JSON</button>' +
      '</div>' +
      '<div class="ne-grid" role="region" aria-label="Native byte grid"></div>' +
      '<p class="ne-status" role="status" aria-live="polite"></p>';
    document.body.appendChild(panel);
    wire();
  }
  function renderTabs() {
    panel.querySelector('.ne-cats').innerHTML = CATS.map(function (c, i) {
      return '<button type="button" class="ne-cat' + (i === curCat ? ' on' : '') + '" role="tab" ' +
        'aria-selected="' + (i === curCat) + '" data-cat="' + i + '">' + c.label + '</button>';
    }).join('');
  }
  function renderSlotMax() {
    var cat = CATS[curCat], si = panel.querySelector('.ne-slot');
    si.max = cat.slots - 1; si.value = curSlot;
    panel.querySelector('.ne-slothex').textContent =
      cat.unit + ' ' + curSlot + ' / ' + (cat.slots - 1) + '  (hex ' + hex2(curSlot) + ')';
  }
  function renderExports() {
    var sav = panel.querySelector('.ne-exp-sav');
    if (sav) sav.style.display = (state && state.savBytes) ? '' : 'none';
  }
  function renderGrid() {
    var cat = CATS[curCat], h = '<table class="ne-table"><thead><tr>';
    if (cat.rows > 1) h += '<th scope="col" class="ne-rh">' + cat.rowLabel + '</th>';
    for (var c = 0; c < cat.cols.length; c++) h += '<th scope="col">' + cat.cols[c].l + '</th>';
    h += '</tr></thead><tbody>';
    for (var row = 0; row < cat.rows; row++) {
      h += '<tr>';
      if (cat.rows > 1) h += '<th scope="row" class="ne-rh">' + hex2(row) + '</th>';
      for (var ci = 0; ci < cat.cols.length; ci++) {
        var lab = cat.label + ' ' + cat.unit + ' ' + curSlot +
          (cat.rows > 1 ? ' ' + cat.rowLabel + ' ' + row : '') + ' ' + cat.cols[ci].l;
        h += '<td><input class="ne-byte" type="text" spellcheck="false" autocomplete="off" maxlength="2" ' +
          'data-row="' + row + '" data-col="' + ci + '" aria-label="' + lab + '" ' +
          'value="' + hex2(getByte(cat, curSlot, row, ci)) + '"></td>';
      }
      h += '</tr>';
    }
    h += '</tbody></table>';
    panel.querySelector('.ne-grid').innerHTML = h;
  }
  function updateHistory() {
    var u = panel.querySelector('.ne-undo'), r = panel.querySelector('.ne-redo');
    if (u) u.disabled = !state.doc.canUndo();
    if (r) r.disabled = !state.doc.canRedo();
  }

  function onByteChange(inp) {
    var cat = CATS[curCat], row = +inp.dataset.row, ci = +inp.dataset.col;
    var a = cat.cols[ci].at(curSlot, row);
    var v = parseHexByte((inp.value || '').trim());
    if (v == null) { inp.value = hex2(getByte(cat, curSlot, row, ci)); status('Enter a hex byte 00\u2013FF'); return; }
    try {
      state.doc.setFieldByte(a.key, a.i, a.j, v);
      inp.value = hex2(v); state.dirty = true; updateHistory();
      status('Set ' + cat.label + ' ' + cat.unit + ' ' + curSlot +
        (cat.rows > 1 ? ' ' + cat.rowLabel + ' ' + row : '') + ' ' + cat.cols[ci].l + ' = ' + hex2(v));
    } catch (e) {
      inp.value = hex2(getByte(cat, curSlot, row, ci));
      status(String(e && e.message || e));
    }
  }
  function setSlot(v) {
    var cat = CATS[curCat];
    v = Math.round(+v || 0); if (!(v >= 0)) v = 0;
    v = Math.max(0, Math.min(cat.slots - 1, v));
    curSlot = v; renderSlotMax(); renderGrid();
  }
  function doUndo() { if (state.doc.undo()) { renderGrid(); updateHistory(); status('Undid one edit'); } else status('Nothing to undo'); }
  function doRedo() { if (state.doc.redo()) { renderGrid(); updateHistory(); status('Redid one edit'); } else status('Nothing to redo'); }

  function exportLsdsng() {
    try {
      var song = state.doc.toSong(), body = LS().compress(song, 1);
      var file = new Uint8Array(9 + body.length);
      file.set(projName(state.title), 0); file[8] = 0; file.set(body, 9);
      if (saveBytes(file, safeName(state.title) + '-edited.lsdsng'))
        status('Saved ' + safeName(state.title) + '-edited.lsdsng \u2014 ' + state.doc.dirtyFields().length + ' field group(s) changed');
    } catch (e) { status('Export failed: ' + String(e && e.message || e)); }
  }
  function exportSav() {
    if (!state.savBytes) { status('No .sav was opened, so only .lsdsng can be written'); return; }
    try {
      var out = Uint8Array.from(state.savBytes);
      out.set(state.doc.toSong(), 0);                 // working-memory song only; rest retained
      if (saveBytes(out, safeName(state.title) + '-edited.sav'))
        status('Saved ' + safeName(state.title) + '-edited.sav \u2014 working-memory song updated, other slots untouched');
    } catch (e) { status('Export failed: ' + String(e && e.message || e)); }
  }
  function exportJson() {
    try {
      var s = state.doc.serializeFull();
      if (saveBytes(new TextEncoder().encode(s), safeName(state.title) + '-native.json', 'application/json'))
        status('Saved native structure JSON \u2014 a file to reopen here, not a playable link');
    } catch (e) { status('Export failed: ' + String(e && e.message || e)); }
  }

  function wire() {
    panel.addEventListener('click', function (ev) {
      var t = ev.target;
      if (t.closest('.ne-close')) { close(); return; }
      var cat = t.closest('.ne-cat');
      if (cat) { curCat = +cat.dataset.cat; curSlot = 0; renderTabs(); renderSlotMax(); renderGrid(); return; }
      if (t.closest('.ne-undo')) { doUndo(); return; }
      if (t.closest('.ne-redo')) { doRedo(); return; }
      if (t.closest('.ne-exp-sng')) { exportLsdsng(); return; }
      if (t.closest('.ne-exp-sav')) { exportSav(); return; }
      if (t.closest('.ne-exp-json')) { exportJson(); return; }
      if (t.closest('.ne-imp-json')) { ensureInputs(); jsonInput.click(); return; }
    });
    panel.addEventListener('change', function (ev) {
      var inp = ev.target.closest('.ne-byte'); if (inp) { onByteChange(inp); return; }
      var s = ev.target.closest('.ne-slot'); if (s) { setSlot(s.value); }
    });
    panel.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') close(); });
  }

  function open(o) {
    ensureInputs();
    state = { doc: o.doc, savBytes: o.savBytes || null, title: o.name || 'CHIPTUNE', dirty: false };
    // Coexist with Create, but silence its playback on entry (we do not play the
    // native song, and claiming otherwise would be a false parity).
    if (G.CT_CREATE && G.CT_CREATE.stopForNative) { try { G.CT_CREATE.stopForNative(); } catch (e) {} }
    buildPanel();
    curCat = 0; curSlot = 0;
    var nm = panel.querySelector('.ne-name'); if (nm) nm.textContent = state.title;
    renderExports(); renderTabs(); renderSlotMax(); renderGrid(); updateHistory();
    panel.classList.add('show');
    document.body.classList.add('native-open');
    var c = panel.querySelector('.ne-close'); if (c) c.focus();
    status('Opened ' + state.title + ' \u2014 structural editing only, no playback');
  }
  function close() {
    if (panel) panel.classList.remove('show');
    document.body.classList.remove('native-open');
  }
  function isOpen() { return !!(panel && panel.classList.contains('show')); }

  G.CT_LSDJ_NATIVE_EDITOR = { pick: pick, open: open, close: close, isOpen: isOpen };
  if (typeof module !== 'undefined' && module.exports) module.exports = G.CT_LSDJ_NATIVE_EDITOR;
})(typeof globalThis !== 'undefined' ? globalThis : window);

