// REAL USER-FACING NATIVE EDITING, DRIVEN THROUGH THE ACTUAL DOM.
//
// Opens a local .lsdsng in the native structure editor reached from Create,
// edits a phrase / instrument / table byte, undoes and redoes, exports, and
// proves the exported song changed EXACTLY the intended offsets while an
// unmapped sentinel byte survived. Also: a standalone native-JSON share
// reimports, a malicious upload is rejected without losing the open document,
// and the panel fits a phone with keyboard-focusable cells.
'use strict';
const fs = require('fs');
const http = require('http');
const path = require('path');
const { chromium } = require('playwright');

const ROOT = path.join(__dirname, '..');
const DIST = path.join(ROOT, 'dist');
const LSDJ = require(path.join(ROOT, 'src', 'lsdj.js'));
const wait = ms => new Promise(r => setTimeout(r, ms));
let fail = 0;
const ok = (c, m) => { console.log((c ? '  ok   ' : '  FAIL ') + m); if (!c) fail++; };

const O = LSDJ.OFFSETS;
const T0 = LSDJ.FIELDS.find(f => f.k === 'tables0').at;   // 0x3480
const SENTINEL = 0x1700;                                  // unmapped by the field table

function fixture() {
  const song = Uint8Array.from(LSDJ.emptySong());
  song[SENTINEL] = 0xAB;
  const body = LSDJ.compress(song, 1);
  const name = new Uint8Array(8);
  'FIXTURE'.split('').forEach((c, i) => { name[i] = c.charCodeAt(0); });
  const file = new Uint8Array(9 + body.length);
  file.set(name, 0); file[8] = 0; file.set(body, 9);
  return { file, song };
}

function server() {
  return new Promise(res => {
    const s = http.createServer((q, e) => {
      let rel = decodeURIComponent(new URL(q.url, 'http://x').pathname).replace(/^\/+/, '');
      let f = path.join(DIST, rel || 'index.html');
      if (!f.startsWith(DIST) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) f = path.join(DIST, 'index.html');
      fs.readFile(f, (err, b) => {
        if (err) { e.writeHead(500); e.end(); return; }
        e.writeHead(200, { 'content-type': f.endsWith('.js') ? 'text/javascript' : 'text/html' });
        e.end(b);
      });
    });
    s.listen(0, '127.0.0.1', () => res({ s, port: s.address().port }));
  });
}

const setCat = (p, id) => p.evaluate(id => {
  const b = [...document.querySelectorAll('#nativeeditor .ne-cat')].find(x => x.textContent.trim().toLowerCase() === id);
  if (b) b.click();
}, id);
const setSlot = (p, n) => p.evaluate(n => {
  const s = document.querySelector('#nativeeditor .ne-slot');
  s.value = String(n); s.dispatchEvent(new Event('change', { bubbles: true }));
}, n);
const setByte = (p, row, col, hex) => p.evaluate(a => {
  const inp = document.querySelector('#nativeeditor .ne-byte[data-row="' + a.row + '"][data-col="' + a.col + '"]');
  inp.value = a.hex; inp.dispatchEvent(new Event('change', { bubbles: true }));
}, { row, col, hex });
const getByte = (p, row, col) => p.evaluate(a =>
  (document.querySelector('#nativeeditor .ne-byte[data-row="' + a.row + '"][data-col="' + a.col + '"]') || {}).value,
  { row, col });

(async () => {
  if (!fs.existsSync(path.join(DIST, 'index.html'))) { console.error('  FAIL  dist/ is not built; run the build first'); process.exit(1); }
  const fx = fixture();
  const h = await server();
  const b = await chromium.launch({ headless: true, args: ['--autoplay-policy=no-user-gesture-required'] });

  // ---- desktop: the whole edit / export / reimport / reject cycle ----------
  {
    const p = await b.newPage({ viewport: { width: 1280, height: 900 }, acceptDownloads: true });
    const errs = []; p.on('pageerror', e => errs.push(String(e).slice(0, 160)));
    await p.goto(`http://127.0.0.1:${h.port}/create`, { waitUntil: 'domcontentloaded' });
    await p.waitForFunction(() => document.querySelector('#createscreen.show'), null, { timeout: 40000 });
    await wait(1200);
    await p.evaluate(() => { const t = document.querySelector('.cr-tour'); if (t) t.remove(); });

    // Open LSDj -> a real file chooser -> hand it the fixture .lsdsng.
    const [chooser] = await Promise.all([
      p.waitForEvent('filechooser'),
      p.click('[data-cr="opennative"]')
    ]);
    await chooser.setFiles({ name: 'fixture.lsdsng', mimeType: 'application/octet-stream', buffer: Buffer.from(fx.file) });
    await p.waitForFunction(() => document.querySelector('#nativeeditor.show'), null, { timeout: 15000 });
    await wait(400);

    const banner = await p.evaluate(() => (document.querySelector('#nativeeditor .ne-banner') || {}).textContent || '');
    ok(/not implemented/i.test(banner), 'the panel states native playback is not implemented');

    // edit a phrase note, an instrument param, and a table byte
    await setCat(p, 'phrases'); await setSlot(p, 3); await setByte(p, 5, 0, '2A');
    await setCat(p, 'instruments'); await setSlot(p, 2); await setByte(p, 7, 0, 'C0');
    await setCat(p, 'tables'); await setSlot(p, 1); await setByte(p, 4, 0, '0C');
    ok(await getByte(p, 4, 0) === '0C', 'a table byte edit shows in the grid');

    // undo reverts the last (table) edit; redo restores it
    await p.click('#nativeeditor .ne-undo'); await wait(150);
    ok(await getByte(p, 4, 0) === '00', 'undo reverts the table edit to its original byte');
    await p.click('#nativeeditor .ne-redo'); await wait(150);
    ok(await getByte(p, 4, 0) === '0C', 'redo re-applies the table edit');

    // export .lsdsng and check exact offsets + sentinel
    const [dl] = await Promise.all([ p.waitForEvent('download'), p.click('#nativeeditor .ne-exp-sng') ]);
    const outSong = LSDJ.parseLsdsng(new Uint8Array(fs.readFileSync(await dl.path()))).song;
    const pOff = O.PHRASE_NOTES + 3 * 16 + 5, iOff = O.INSTRUMENT_PARAMS + 2 * 16 + 7, tOff = T0 + 1 * 16 + 4;
    let diffs = [];
    for (let k = 0; k < LSDJ.SONG_BYTES; k++) if (outSong[k] !== fx.song[k]) diffs.push(k);
    ok(diffs.length === 3 && diffs.includes(pOff) && diffs.includes(iOff) && diffs.includes(tOff),
       'the export changed exactly the three edited offsets and nothing else');
    ok(outSong[pOff] === 0x2A && outSong[iOff] === 0xC0 && outSong[tOff] === 0x0C, 'the edited bytes hold their values');
    ok(outSong[SENTINEL] === 0xAB, 'the unmapped sentinel byte is preserved through export');

    // standalone native share: save JSON, reopen it, confirm an edit survives
    const [dlj] = await Promise.all([ p.waitForEvent('download'), p.click('#nativeeditor .ne-exp-json') ]);
    const jtxt = fs.readFileSync(await dlj.path(), 'utf8');
    ok(/"mode":"full"/.test(jtxt), 'the native share is a standalone full document (not a diff)');
    const [chj] = await Promise.all([ p.waitForEvent('filechooser'), p.click('#nativeeditor .ne-imp-json') ]);
    await chj.setFiles({ name: 'doc.json', mimeType: 'application/json', buffer: Buffer.from(jtxt) });
    await wait(400);
    await setCat(p, 'phrases'); await setSlot(p, 3);
    ok(await getByte(p, 5, 0) === '2A', 'a reimported native-JSON share carries the edit back');

    // malicious upload: rejected before reading, current document untouched
    await setCat(p, 'phrases'); await setSlot(p, 3);
    const before = await getByte(p, 5, 0);
    const [chBad] = await Promise.all([ p.waitForEvent('filechooser'), p.evaluate(() => CT_LSDJ_NATIVE_EDITOR.pick()) ]);
    await chBad.setFiles({ name: 'evil.lsdsng', mimeType: 'application/octet-stream', buffer: Buffer.alloc(300000, 0x99) });
    await wait(400);
    const stillOpen = await p.evaluate(() => !!document.querySelector('#nativeeditor.show'));
    ok(stillOpen && (await getByte(p, 5, 0)) === before, 'an oversized/malicious upload is rejected without losing the open document');

    ok(!errs.length, 'no page errors during the native edit cycle' + (errs.length ? ' -- ' + errs[0] : ''));
    await p.close();
  }

  // ---- phone: the panel fits and its cells are keyboard-focusable ----------
  {
    const p = await b.newPage({ viewport: { width: 390, height: 844 }, acceptDownloads: true });
    const errs = []; p.on('pageerror', e => errs.push(String(e).slice(0, 160)));
    await p.goto(`http://127.0.0.1:${h.port}/create`, { waitUntil: 'domcontentloaded' });
    await p.waitForFunction(() => document.querySelector('#createscreen.show'), null, { timeout: 40000 });
    await wait(1000);
    await p.evaluate(() => { const t = document.querySelector('.cr-tour'); if (t) t.remove(); });
    const [chooser] = await Promise.all([
      p.waitForEvent('filechooser'),
      p.click('[data-cr="opennative"]')
    ]);
    await chooser.setFiles({ name: 'fixture.lsdsng', mimeType: 'application/octet-stream', buffer: Buffer.from(fx.file) });
    await p.waitForFunction(() => document.querySelector('#nativeeditor.show'), null, { timeout: 15000 });
    await wait(400);
    const box = await p.evaluate(() => {
      const r = document.getElementById('nativeeditor').getBoundingClientRect();
      return { left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top),
               bottom: Math.round(r.bottom), vw: innerWidth, vh: innerHeight };
    });
    ok(box.left >= -1 && box.right <= box.vw + 1 && box.top >= -1 && box.bottom <= box.vh + 1,
       'the panel fits within a 390x844 phone viewport');
    const focused = await p.evaluate(() => {
      const inp = document.querySelector('#nativeeditor .ne-byte'); if (!inp) return false;
      inp.focus(); return document.activeElement === inp;
    });
    ok(focused, 'a byte cell is keyboard-focusable on a phone');
    ok(!errs.length, 'no page errors on the phone layout' + (errs.length ? ' -- ' + errs[0] : ''));
    await p.close();
  }

  await b.close(); h.s.close();
  console.log(fail ? ('\n' + fail + ' check(s) failed') : '\nlsdj-native-editor: all checks passed');
  process.exit(fail ? 1 : 0);
})();

